#!/usr/bin/env node
// Brings the listed first-party extensions the demo runs into vendor/, at the commits vendor/extensions.json pins:
// each one's manifest and built UI bundle (gitignored, fetched before every build), and for knowledge the fs-free half
// of its engine as source (committed, so the fixture that stands in for its backend type-checks offline).
//
//   node scripts/sync-extensions.mjs                       # from GitHub, at the pinned shas
//   node scripts/sync-extensions.mjs --local ../../../extensions   # from local checkouts, one directory per extension
//
// A pin is the registry's own commit for that extension: the demo runs exactly the bytes an install would.
//
// The engine copy is re-fetched only when its pin moves — vendor/knowledge/source.json names the commit it holds —
// so an ordinary build reads raw.githubusercontent alone and never the rate-limited api.github.com.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const here = import.meta.dirname;
const vendor = join(here, "..", "vendor");
const pins = JSON.parse(readFileSync(join(vendor, "extensions.json"), "utf8"));

const localAt = process.argv.indexOf("--local");
const local = localAt === -1 ? undefined : process.argv[localAt + 1];
if (localAt !== -1 && local === undefined) {
    console.error("--local needs the directory holding one checkout per extension");
    process.exit(2);
}

// The knowledge engine's fs-free half: everything notes/index.ts reaches, and nothing that touches the filesystem.
const KNOWLEDGE_ENGINE = { id: "intentic.knowledge", dir: "src/notes", skip: /(\.test\.ts|read-notes\.ts)$/, types: "src/wire-types.ts" };

const SHA = /^[0-9a-f]{40}$/;

// A token lifts GitHub's 60-requests-an-hour anonymous limit, which is per IP and so is shared by every job on a
// runner host; absent is fine, since a build at an unmoved pin asks GitHub for the bundles alone.
const token = process.env.GITHUB_TOKEN ?? process.env.GH_TOKEN;
const headers = token === undefined || token === "" ? {} : { authorization: `Bearer ${token}` };

const fetchText = async (url) => {
    const response = await fetch(url, { headers });
    if (!response.ok) {
        throw new Error(`${url}: ${response.status} ${response.statusText}`);
    }
    return response.text();
};

// One source per pin: a local checkout, or GitHub at the exact commit.
const sourceFor = (id, pin) => {
    const name = id.slice(id.indexOf(".") + 1);
    if (local !== undefined) {
        const root = join(local, name);
        return {
            label: root,
            read: async (path) => readFileSync(join(root, path), "utf8"),
            list: async (dir) => readdirSync(join(root, dir)).filter((entry) => entry.endsWith(".ts")),
            commit: pin.sha,
        };
    }
    if (!SHA.test(pin.sha)) {
        return undefined;
    }
    const raw = `https://raw.githubusercontent.com/${pin.repo}/${pin.sha}`;
    return {
        label: `${pin.repo}@${pin.sha.slice(0, 12)}`,
        read: (path) => fetchText(`${raw}/${path}`),
        list: async (dir) => {
            const listing = JSON.parse(await fetchText(`https://api.github.com/repos/${pin.repo}/contents/${dir}?ref=${pin.sha}`));
            return listing.filter((entry) => entry.type === "file" && entry.name.endsWith(".ts")).map((entry) => entry.name);
        },
        commit: pin.sha,
    };
};

const header = (source) => `// Generated by scripts/sync-extensions.mjs from ${source.label}: do not edit, re-run the sync.\n`;

for (const [id, pin] of Object.entries(pins)) {
    const source = sourceFor(id, pin);
    const out = join(vendor, "extensions", id);
    if (source === undefined) {
        // Not installed in this recording rather than a failed build: a pin is written the moment the listing exists.
        console.warn(`${id}: pin "${pin.sha}" is not a commit sha, so this extension is left out of the demo until it is published and pinned`);
        rmSync(out, { recursive: true, force: true });
        continue;
    }
    rmSync(out, { recursive: true, force: true });
    mkdirSync(out, { recursive: true });
    writeFileSync(join(out, "intentic-extension.json"), await source.read("intentic-extension.json"));
    writeFileSync(join(out, "extension.js"), await source.read("dist/extension.js"));
    console.log(`${id}: manifest and bundle from ${source.label}`);

    if (id === KNOWLEDGE_ENGINE.id) {
        const engine = join(vendor, "knowledge");
        const marker = join(engine, "source.json");
        // The engine copy is COMMITTED, so a build that did not move the pin has nothing to fetch — and skipping it
        // keeps the only api.github.com call in this script (the notes listing) out of every build. That call is
        // anonymous at 60 an hour per IP, shared by every job on a runner host, which is how a green pipeline began
        // failing on "403 rate limit exceeded". A --local sync writes a working tree rather than the pinned commit,
        // so it leaves no marker and the next sync from GitHub restores the pin.
        const synced = existsSync(marker) ? JSON.parse(readFileSync(marker, "utf8")) : undefined;
        if (local === undefined && synced?.repo === pin.repo && synced?.sha === pin.sha) {
            console.log(`${id}: engine source already at ${source.label}`);
            continue;
        }
        // Every file in hand BEFORE the committed copy is touched: a read that throws half way used to leave the tree
        // with the engine deleted, which is a failed fetch turning into a working tree that no longer type-checks.
        const fetched = [[join(engine, "wire-types.ts"), header(source) + (await source.read(KNOWLEDGE_ENGINE.types))]];
        for (const file of await source.list(KNOWLEDGE_ENGINE.dir)) {
            if (KNOWLEDGE_ENGINE.skip.test(file)) {
                continue;
            }
            fetched.push([join(engine, "notes", file), header(source) + (await source.read(`${KNOWLEDGE_ENGINE.dir}/${file}`))]);
        }
        rmSync(engine, { recursive: true, force: true });
        mkdirSync(join(engine, "notes"), { recursive: true });
        for (const [path, text] of fetched) {
            writeFileSync(path, text);
        }
        if (local === undefined) {
            writeFileSync(marker, `${JSON.stringify({ repo: pin.repo, sha: pin.sha }, undefined, 4)}\n`);
        }
        console.log(`${id}: engine source into vendor/knowledge`);
    }
}
